import type { FC } from 'react';
import { useState } from 'react';
import { toast } from 'sonner';
import { Plus, X } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { parseHex } from '@/lib/color/convert';
import { getContrastRatio, WCAG_THRESHOLDS } from '@/lib/contrast/wcag';
import type { RgbValue } from '@/lib/color/types';

interface AdditionalColorsCheckerProps {
  background: RgbValue;
  colors: string[];
  onAdd: (hex: string) => void;
  onRemove: (hex: string) => void;
}

// Lets you check a whole set of candidate text colors against one background
// at a glance — e.g. pasting in a palette to see which entries are usable as
// body text on it, instead of checking one pair at a time.
const AdditionalColorsChecker: FC<AdditionalColorsCheckerProps> = ({ background, colors, onAdd, onRemove }) => {
  const [draft, setDraft] = useState('#000000');

  const handleAdd = () => {
    const rgb = parseHex(draft);
    if (!rgb) {
      toast.error('Enter a valid hex color');
      return;
    }
    onAdd(draft);
  };

  return (
    <div>
      <h2 className="text-sm font-medium text-muted-foreground mb-3">
        Check more text colors against this background
      </h2>

      <div className="flex items-center gap-2 mb-3">
        <input
          type="color"
          value={/^#[0-9a-fA-F]{6}$/.test(draft) ? draft : '#000000'}
          onChange={(e) => setDraft(e.target.value)}
          aria-label="Pick a color to add"
          className="w-10 h-10 rounded-md border border-input bg-background p-0.5 cursor-pointer shrink-0"
        />
        <Input
          type="text"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
          placeholder="#000000"
          aria-label="Hex color to add"
          spellCheck={false}
          className="font-mono uppercase"
        />
        <button
          type="button"
          onClick={handleAdd}
          aria-label="Add color"
          className="shrink-0 p-2.5 rounded-lg border border-border text-foreground/70 hover:text-foreground hover:border-accent/40 transition-colors"
        >
          <Plus className="w-4 h-4" />
        </button>
      </div>

      {colors.length > 0 && (
        <div className="space-y-2">
          {colors.map((hex) => {
            const rgb = parseHex(hex);
            if (!rgb) return null;
            const ratio = getContrastRatio(rgb, background);
            const passesAA = ratio >= WCAG_THRESHOLDS.aaNormal;

            return (
              <div
                key={hex}
                className="glass-panel hover:border-border flex items-center gap-3 px-4 py-2.5"
              >
                <div
                  className="w-8 h-8 rounded-md border border-border shrink-0"
                  style={{ backgroundColor: hex }}
                />
                <span className="font-mono text-sm text-foreground flex-1 min-w-0 truncate">
                  {hex.toUpperCase()}
                </span>
                <span className="font-mono text-sm text-muted-foreground shrink-0">
                  {ratio.toFixed(2)}:1
                </span>
                <span
                  className={`shrink-0 text-xs font-semibold px-2 py-0.5 rounded-full ${
                    passesAA ? 'bg-emerald-500/15 text-emerald-400' : 'bg-destructive/15 text-destructive'
                  }`}
                >
                  {passesAA ? 'AA Pass' : 'AA Fail'}
                </span>
                <button
                  type="button"
                  onClick={() => onRemove(hex)}
                  aria-label={`Remove ${hex}`}
                  className="shrink-0 p-1.5 rounded-full text-muted-foreground hover:text-accent hover:bg-accent/10 transition-colors"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default AdditionalColorsChecker;
