import type { FC } from 'react';
import { useMemo, useState } from 'react';
import { toast } from 'sonner';
import { Shuffle, RefreshCw, Copy, Check } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import ColorField from '@/components/tools/ColorField';
import PillGroup from '@/components/tools/PillGroup';
import ShareButton from '@/components/tools/ShareButton';
import LivePreview from '@/components/tools/contrast-checker/LivePreview';
import RatioDisplay from '@/components/tools/contrast-checker/RatioDisplay';
import ComplianceBadges from '@/components/tools/contrast-checker/ComplianceBadges';
import AdditionalColorsChecker from '@/components/tools/contrast-checker/AdditionalColorsChecker';
import InfoSection from '@/components/tools/contrast-checker/InfoSection';
import { usePersistentState } from '@/hooks/usePersistentState';
import { buildShareUrl } from '@/lib/share/encode';
import { formatHex, parseHex } from '@/lib/color/convert';
import { checkWcagCompliance, getContrastRatio, WCAG_THRESHOLDS } from '@/lib/contrast/wcag';
import { getApcaScore } from '@/lib/contrast/apca';
import { fixContrastToRatio } from '@/lib/contrast/fixContrast';
import { CVD_MODE_LABELS, simulateColorBlindness, type CvdMode } from '@/lib/contrast/colorBlindness';

const CVD_OPTIONS = (Object.keys(CVD_MODE_LABELS) as CvdMode[]).map((mode) => ({
  value: mode,
  label: CVD_MODE_LABELS[mode],
}));

function randomHex(): string {
  const n = Math.floor(Math.random() * 0xffffff);
  return `#${n.toString(16).padStart(6, '0')}`;
}

const buttonBase =
  'inline-flex items-center justify-center gap-1.5 px-3.5 py-2 rounded-lg text-sm font-medium border border-border text-foreground/80 hover:text-foreground hover:border-accent/40 transition-colors disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:border-border';

const ContrastChecker: FC = () => {
  const [bgHex, setBgHex] = usePersistentState<string>('contrast-checker:bg', '#1a1a2e');
  const [fgHex, setFgHex] = usePersistentState<string>('contrast-checker:fg', '#eaeaea');
  const [cvdMode, setCvdMode] = usePersistentState<CvdMode>('contrast-checker:cvd', 'normal');
  const [additionalColors, setAdditionalColors] = usePersistentState<string[]>(
    'contrast-checker:additional',
    [],
  );
  const [copiedKind, setCopiedKind] = useState<'css' | 'summary' | null>(null);

  const bgRgb = useMemo(() => parseHex(bgHex), [bgHex]);
  const fgRgb = useMemo(() => parseHex(fgHex), [fgHex]);
  const valid = !!bgRgb && !!fgRgb;

  const ratio = valid ? getContrastRatio(fgRgb, bgRgb) : 0;
  const apcaScore = valid ? getApcaScore(fgRgb, bgRgb) : 0;
  const compliance = valid ? checkWcagCompliance(ratio) : null;

  const displayBg = valid ? formatHex(simulateColorBlindness(bgRgb, cvdMode)) : bgHex;
  const displayFg = valid ? formatHex(simulateColorBlindness(fgRgb, cvdMode)) : fgHex;

  const handleFlip = () => {
    setBgHex(fgHex);
    setFgHex(bgHex);
  };

  const handleRandomPair = () => {
    setBgHex(randomHex());
    setFgHex(randomHex());
  };

  const handleFix = (targetRatio: number) => {
    if (!valid) return;
    const fixed = fixContrastToRatio(fgRgb, bgRgb, targetRatio);
    setFgHex(formatHex(fixed));

    // Some backgrounds simply can't reach a given target with any foreground —
    // e.g. a mid-luminance background where even pure black or white falls
    // short. Say so instead of leaving the user staring at a still-red badge.
    const achieved = getContrastRatio(fixed, bgRgb);
    if (achieved < targetRatio - 0.01) {
      toast.warning(
        `Closest possible against this background is ${achieved.toFixed(2)}:1 — ${targetRatio}:1 isn't reachable here even with pure black or white. Try a different background.`,
      );
    }
  };

  const handleAddColor = (hex: string) => {
    const rgb = parseHex(hex);
    if (!rgb) return;
    const normalized = formatHex(rgb);
    setAdditionalColors((prev) => (prev.includes(normalized) ? prev : [...prev, normalized]));
  };

  const handleRemoveColor = (hex: string) => {
    setAdditionalColors((prev) => prev.filter((c) => c !== hex));
  };

  const copy = async (kind: 'css' | 'summary') => {
    if (!valid || !compliance) return;
    const text =
      kind === 'css'
        ? `/* Contrast ${ratio.toFixed(2)}:1 */\n--color-bg: ${bgHex};\n--color-fg: ${fgHex};`
        : `${bgHex} on ${fgHex} — ${ratio.toFixed(2)}:1 (${compliance.aaNormal ? 'AA' : 'fails AA'}${compliance.aaaNormal ? ', AAA' : ''})`;
    try {
      await navigator.clipboard.writeText(text);
      setCopiedKind(kind);
      toast.success(kind === 'css' ? 'Copied CSS' : 'Copied summary');
      window.setTimeout(() => setCopiedKind((c) => (c === kind ? null : c)), 1500);
    } catch {
      toast.error('Copy failed');
    }
  };

  return (
    <ToolLayout
      title="Contrast Checker"
      description="Check WCAG 2.1 and APCA contrast between two colors, preview it under color vision deficiencies, and fix it automatically."
    >
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-8">
          {/* Just the color inputs + action buttons — kept as its own compact
              box, not stretched to hold the rest of the left column's content. */}
          <div className="glass-panel hover:border-border p-6 md:p-8 space-y-5">
            <ColorField label="Background Color" value={bgHex} onChange={setBgHex} />
            <ColorField label="Foreground (Text) Color" value={fgHex} onChange={setFgHex} />

            <div className="flex flex-wrap gap-2">
              <button type="button" onClick={handleFlip} className={buttonBase}>
                <RefreshCw className="w-3.5 h-3.5" />
                Flip Colors
              </button>
              <button type="button" onClick={handleRandomPair} className={buttonBase}>
                <Shuffle className="w-3.5 h-3.5" />
                Random Pair
              </button>
              <button
                type="button"
                onClick={() => handleFix(WCAG_THRESHOLDS.aaNormal)}
                disabled={!valid || !!compliance?.aaNormal}
                className={`${buttonBase} bg-accent/10 border-accent/30`}
              >
                Fix to AA
              </button>
              <button
                type="button"
                onClick={() => handleFix(WCAG_THRESHOLDS.aaaNormal)}
                disabled={!valid || !!compliance?.aaaNormal}
                className={`${buttonBase} bg-accent/10 border-accent/30`}
              >
                Fix to AAA
              </button>
            </div>

            {!valid && <p className="text-xs text-destructive">Enter valid hex colors for both fields.</p>}
          </div>

          {valid && bgRgb && (
            <AdditionalColorsChecker
              background={bgRgb}
              colors={additionalColors}
              onAdd={handleAddColor}
              onRemove={handleRemoveColor}
            />
          )}

          <div>
            <h2 className="text-sm font-medium text-muted-foreground mb-3">Simulate color vision</h2>
            <PillGroup aria-label="Color vision simulation" options={CVD_OPTIONS} value={cvdMode} onChange={setCvdMode} />
          </div>

          <InfoSection />
        </div>

        <div className="space-y-8">
          <div>
            <div className="flex items-center justify-between flex-wrap gap-3 mb-3">
              <h2 className="text-sm font-medium text-muted-foreground">Live Preview</h2>
              {valid && compliance && (
                <div className="flex gap-2">
                  <button type="button" onClick={() => copy('css')} className={buttonBase}>
                    {copiedKind === 'css' ? <Check className="w-3.5 h-3.5 text-accent" /> : <Copy className="w-3.5 h-3.5" />}
                    Copy CSS
                  </button>
                  <button type="button" onClick={() => copy('summary')} className={buttonBase}>
                    {copiedKind === 'summary' ? <Check className="w-3.5 h-3.5 text-accent" /> : <Copy className="w-3.5 h-3.5" />}
                    Copy Summary
                  </button>
                  <ShareButton
                    className={buttonBase}
                    getUrl={() => buildShareUrl('/tools/contrast-checker/share', { bg: bgHex, fg: fgHex })}
                  />
                </div>
              )}
            </div>
            <LivePreview backgroundHex={displayBg} foregroundHex={displayFg} />
          </div>

          {valid && compliance && (
            <>
              <div className="glass-panel hover:border-border p-6">
                <RatioDisplay ratio={ratio} apcaScore={apcaScore} />
              </div>

              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">WCAG 2.1 Compliance</h2>
                <ComplianceBadges compliance={compliance} />
              </div>
            </>
          )}
        </div>
      </div>
    </ToolLayout>
  );
};

export default ContrastChecker;
