import type { RgbValue } from '@/lib/color/types';
import { hslToRgb, rgbToHsl } from '@/lib/color/convert';
import { getContrastRatio, getRelativeLuminance } from './wcag';

function findLightnessForLuminance(hue: number, saturation: number, targetLum: number): number | null {
  if (targetLum < 0 || targetLum > 1) return null;
  let low = 0;
  let high = 100;
  let mid = 50;
  for (let i = 0; i < 50; i++) {
    mid = (low + high) / 2;
    const lum = getRelativeLuminance(hslToRgb({ h: hue, s: saturation, l: mid }));
    if (Math.abs(lum - targetLum) < 0.001) return mid;
    if (lum < targetLum) low = mid;
    else high = mid;
  }
  return mid;
}

/**
 * Adjusts colorToFix's lightness (keeping its hue/saturation) to the closest
 * value that reaches targetRatio against reference. Tries both lighter and
 * darker directions and picks whichever changes the original color less.
 */
export function fixContrastToRatio(colorToFix: RgbValue, reference: RgbValue, targetRatio: number): RgbValue {
  const refLum = getRelativeLuminance(reference);
  const hsl = rgbToHsl(colorToFix);

  const targetLumLight = targetRatio * (refLum + 0.05) - 0.05;
  const targetLumDark = (refLum + 0.05) / targetRatio - 0.05;

  const lightnessLight = findLightnessForLuminance(hsl.h, hsl.s, targetLumLight);
  const lightnessDark = findLightnessForLuminance(hsl.h, hsl.s, targetLumDark);

  let bestL: number | null = null;
  let direction: 1 | -1 = 1; // which way we're moving lightness: +1 lighter, -1 darker
  if (lightnessLight !== null && lightnessDark !== null) {
    const useLight = Math.abs(lightnessLight - hsl.l) <= Math.abs(lightnessDark - hsl.l);
    bestL = useLight ? lightnessLight : lightnessDark;
    direction = useLight ? 1 : -1;
  } else if (lightnessLight !== null) {
    bestL = lightnessLight;
    direction = 1;
  } else if (lightnessDark !== null) {
    bestL = lightnessDark;
    direction = -1;
  }

  if (bestL === null) {
    return refLum > 0.5 ? { r: 0, g: 0, b: 0 } : { r: 255, g: 255, b: 255 };
  }

  // The binary search converges on a continuous lightness, but the result
  // has to round to an integer RGB triplet — that rounding can land the
  // *real* ratio just under the target (e.g. 4.49 instead of 4.5). Nudge
  // further in the same direction until the rounded color actually clears it.
  let result = hslToRgb({ h: hsl.h, s: hsl.s, l: bestL });
  let guard = 0;
  while (getContrastRatio(result, reference) < targetRatio && bestL > 0 && bestL < 100 && guard < 200) {
    bestL = Math.min(100, Math.max(0, bestL + direction * 0.5));
    result = hslToRgb({ h: hsl.h, s: hsl.s, l: bestL });
    guard++;
  }

  return result;
}
